icon.color:
[[[if (!entity && this._config?.entity) entity = {entity_id: this._config.entity, state: 'unavailable', attributes: {}};states = new Proxy(states, {get: (t, k) => t[k] ?? (typeof k === 'string' && k.includes('.') ? {entity_id: k, state: 'unavailable', attributes: {}} : undefined)});
