custom_fields.status:
[[[if (!entity && this._config?.entity) entity = {entity_id: this._config.entity, state: 'unavailable', attributes: {}};states = new Proxy(states, {get: (t, k) => t[k] ?? (typeof k === 'string' && k.includes('.') ? {entity_id: k, state: 'unavailable', attributes: {}} : undefined)});
const ps = states['sensor.h2s_00h2s000000001_print_status'];
const s = ps ? ps.state : 'unknown';
const active = ['printing', 'paused', 'preparing'].includes(s);
const scol = {printing: 'var(--fab-y)', finished: 'var(--fab-y)', preparing: 'var(--fab-o)', slicing: 'var(--fab-o)',
              paused: 'var(--fab-o)', failed: 'var(--fab-r)', offline: 'var(--fab-r)'}[s] || 'var(--fab-dim)';

const fmt = (x) => {
  if (!x || ['unavailable', 'unknown', ''].includes(x.state)) return '—';
  const st = x.state, at = x.attributes;
  if (x.entity_id.startsWith('binary_sensor.')) {
    const m = {connectivity: ['ONLINE', 'OFFLINE'], door: ['OPEN', 'CLOSED'], plug: ['PLUGGED IN', 'NONE'],
               problem: ['PROBLEM', 'OK'], running: ['RUNNING', 'IDLE']}[at.device_class] || ['ON', 'OFF'];
    return st === 'on' ? m[0] : m[1];
  }
  if (x.entity_id.startsWith('update.')) return at.installed_version || st;
  const n = Number(st);
  if (!isNaN(n)) return n.toLocaleString('en-US', {maximumFractionDigits: 1}) + (at.unit_of_measurement ? ' ' + at.unit_of_measurement : '');
  return st.replace(/_/g, ' ').toUpperCase();
};

const stg = states['sensor.h2s_00h2s000000001_print_stage'];
const sub = active ? `${fmt(stg)} · ${Math.round(parseFloat(states['sensor.h2s_00h2s000000001_progress'].state) || 0)} %`
                   : ['offline', 'unknown', 'unavailable'].includes(s) ? 'NO CONNECTION' : 'SYSTEM READY';
return `<div style="display:flex;align-items:center;gap:12px">
  <span style="width:13px;height:13px;border-radius:50%;background:${scol};box-shadow:0 0 14px ${scol};${s === 'printing' ? 'animation:fab-blink 1.6s infinite' : ''}"></span>
  <div style="text-align:left"><div style="font-size:21px;letter-spacing:3px;text-transform:uppercase;line-height:1.05;color:${scol}">${fmt(ps)}</div>
