cards.extra_styles:
ha-card { clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px)); }
ha-card::after { content: ''; position: absolute; top: 0; right: 0; width: 16px; height: 16px; background: var(--fab-y);
  clip-path: polygon(0 0, 4px 0, 100% 12px, 100% 100%); pointer-events: none; }
ha-card::before { content: ''; position: absolute; bottom: 0; left: 0; width: 16px; height: 16px; background: rgba(255,180,0,.55);
  clip-path: polygon(0 0, 100% 100%, 12px 100%, 0 4px); pointer-events: none; }

@keyframes fab-blink { 50% { opacity: .25; } }
@keyframes fab-spin { to { transform: rotate(360deg); } }

.fab-sl { user-select: none; width: 100%; }
.fab-sl.off input, .fab-sl.off .fab-sv { opacity: .55; }
.fab-sa { color: var(--fab-txt); opacity: .7; }
.fab-sh { display: flex; justify-content: space-between; align-items: baseline; font-family: var(--fab-mono); font-size: 10.5px;
  letter-spacing: 1.5px; line-height: 1.2; color: var(--fab-txt); }
.fab-sh > span:first-child { opacity: .8; }
.fab-sv { font-family: var(--fab-font); font-size: 16px; letter-spacing: 1px; color: var(--fab-y); }
.fab-sl input { -webkit-appearance: none; appearance: none; display: block; width: 100%; height: 22px; margin: 0;
  background: transparent; cursor: pointer; touch-action: pan-y; outline: none; }
.fab-sl input:disabled { cursor: not-allowed; }
.fab-sl input::-webkit-slider-runnable-track { height: 10px;
  background: repeating-linear-gradient(90deg, transparent 0 6px, #070707 6px 8px),
              linear-gradient(90deg, var(--fab-y) 0 var(--p), #232321 var(--p) 100%) 0 0 / 100% 6px no-repeat,
              linear-gradient(90deg, rgba(255,180,0,.45) 0 var(--a, 0%), #191917 var(--a, 0%) 100%) 0 100% / 100% 3px no-repeat,
              #070707;
  box-shadow: inset 0 0 0 1px rgba(255,180,0,.28), 0 0 14px rgba(255,180,0,.12); }
.fab-sl input::-moz-range-track { height: 10px;
  background: repeating-linear-gradient(90deg, transparent 0 6px, #070707 6px 8px),
              linear-gradient(90deg, var(--fab-y) 0 var(--p), #232321 var(--p) 100%) 0 0 / 100% 6px no-repeat,
              linear-gradient(90deg, rgba(255,180,0,.45) 0 var(--a, 0%), #191917 var(--a, 0%) 100%) 0 100% / 100% 3px no-repeat,
              #070707;
  box-shadow: inset 0 0 0 1px rgba(255,180,0,.28); }
.fab-sl input::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 22px; margin-top: -6px; border: none;
  background: linear-gradient(var(--fab-y), var(--fab-y)) center / 2px 56% no-repeat, #0b0b0b;
  box-shadow: 0 0 0 2px var(--fab-y), 0 0 10px rgba(255,180,0,.5); transition: background-color .15s; }
.fab-sl input::-moz-range-thumb { width: 14px; height: 22px; border: none; border-radius: 0;
  background: linear-gradient(var(--fab-y), var(--fab-y)) center / 2px 56% no-repeat, #0b0b0b;
