custom_fields.hms:
[[[if (!entity && this._config?.entity) entity = {entity_id: this._config.entity, state: 'unavailable', attributes: {}};states = new Proxy(states, {get: (t, k) => t[k] ?? (typeof k === 'string' && k.includes('.') ? {entity_id: k, state: 'unavailable', attributes: {}} : undefined)});
const fabHmsOpen = () => {
  const ps = states['sensor.h2s_00h2s000000001_print_status']?.state, errs = states['sensor.h2s_00h2s000000001_hms_errors']?.attributes.errors || [];
  return errs.filter((x) => (x.actions || []).length || !['notice', 'info', ''].includes(x.severity || '') || ['paused', 'failed'].includes(ps));
};
const fabHmsAlarm = () => {
  const ps = states['sensor.h2s_00h2s000000001_print_status']?.state;
  return fabHmsOpen().filter((x) => (x.actions || []).length || ['paused', 'failed'].includes(ps) || ['serious', 'fatal'].includes(x.severity));
};
const fabHms = (errs) => {
  const col = (s) => ({error: 'var(--fab-r)', serious: 'var(--fab-r)', fatal: 'var(--fab-r)', warning: 'var(--fab-o)'})[s] || 'var(--fab-y)';
  const names = {RESUME_PRINTING: 'Resume', RESUME_PRINTING_DEFECTS: 'Resume anyway', RESUME_PRINTING_PROBELM_SOLVED: 'Solved · resume',
    PROBLEM_SOLVED_RESUME: 'Solved · resume', IGNORE_RESUME: 'Ignore · resume', STOP_PRINTING: 'Stop print', ABORT: 'Abort',
    IGNORE_NO_REMINDER_NEXT_TIME: 'Ignore · no reminder', DONT_REMIND_NEXT_TIME: 'No reminder', NO_REMINDER_NEXT_TIME: 'No reminder',
    OK_BUTTON: 'OK', DBL_CHECK_OK: 'OK'};
  const btn = (x, a) => {
    const stop = ['STOP_PRINTING', 'ABORT'].includes(a);
    const call = `event.stopPropagation();${stop ? "if(!confirm('Stop the print?'))return;" : ''}`
      + `document.querySelector('home-assistant').hass.callService('bambuddy','answer_hms',{device_id:'dev_printer',code:'${x.code}',action:'${a}'})`;
    return `<button onclick="${call}" onpointerdown="event.stopPropagation()" style="font:13px var(--fab-font);letter-spacing:2px;text-transform:uppercase;cursor:pointer;
      padding:4px 12px;border:1px solid ${stop ? 'var(--fab-r)' : 'var(--fab-y)'};background:${stop ? 'rgba(255,46,46,.12)' : 'rgba(255,180,0,.12)'};color:${stop ? 'var(--fab-r)' : 'var(--fab-y)'}">
      ${names[a] || a.replace(/_/g, ' ').toLowerCase()}</button>`;
  };
  return errs.map(x => `<div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:6px 0;border-bottom:1px solid rgba(255,180,0,.12);text-align:left">
    <span style="background:${col(x.severity)};color:#0b0b0b;font-size:11px;font-weight:700;letter-spacing:2px;padding:2px 8px">${(x.severity || '').toUpperCase()}</span>
    <span style="font-family:var(--fab-mono);font-size:12px;color:var(--fab-y)">${x.code}</span>
    <span style="font-family:var(--fab-mono);font-size:12px;flex:1 1 280px;min-width:0;white-space:normal">${x.description || ''}</span>
    ${(x.actions || []).length ? `<span style="display:flex;gap:6px;flex-wrap:wrap">${x.actions.map(a => btn(x, a)).join('')}</span>` : ''}</div>`).join('');
};

const errs = fabHmsAlarm();
if (!errs.length) return '';
const ps = states['sensor.h2s_00h2s000000001_print_status']?.state;
const key = (txt, js) => `<button onclick="event.stopPropagation();${js}" onpointerdown="event.stopPropagation()" style="font:13px var(--fab-font);letter-spacing:2px;
  text-transform:uppercase;cursor:pointer;padding:4px 12px;border:1px solid rgba(255,180,0,.45);background:#0b0b0b;color:var(--fab-txt)">${txt}</button>`;
const cam = "window.dispatchEvent(new CustomEvent('fabricon-camera'))";
return `<div style="margin-bottom:8px;padding:4px 14px 6px;background:linear-gradient(rgba(14,8,6,.92),rgba(14,8,6,.92)),linear-gradient(-45deg, var(--fab-y) 25%, #0b0b0b 25%, #0b0b0b 50%, var(--fab-y) 50%, var(--fab-y) 75%, #0b0b0b 75%);background-size:100% 100%,24px 24px;
  box-shadow:inset 0 0 0 1px var(--fab-o),0 0 18px rgba(255,106,0,.25);text-align:left">
  <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding-top:2px">
    <span style="font-size:17px;letter-spacing:3px;color:var(--fab-o);animation:fab-blink 1.4s infinite">⚠ HMS · ${errs.length} MESSAGE${errs.length > 1 ? 'S' : ''}</span>
    <span style="font-family:var(--fab-mono);font-size:10.5px;letter-spacing:1.5px;color:var(--fab-txt);flex:1;min-width:200px;white-space:normal">${ps === 'paused' ? 'PRINT PAUSED BY THE PRINTER — CHECK THE CAMERA, THEN ANSWER' : 'PRINT ' + (ps || '').toUpperCase()}</span>
    ${key('Camera', cam)}${key('Clear', "document.querySelector('home-assistant').hass.callService('button','press',{entity_id:'button.h2s_00h2s000000001_clear_hms_errors'})")}</div>
  ${fabHms(errs)}</div>`;
]]]

